import {renderDomestic} from './domestic.js';
import {renderTiming,renderRecent,renderDataHub,archiveNav} from './timing-view.js?v=20261023-forecast';
import {renderForecast} from './forecast-view.js?v=20261023-forecast';
import {GPU_NAMES,COMPANY_NAMES,COLORS,finite,inYear,normalizeTogether,stats,stockPairs,miningCorrelation,num,pct,signed,escapeHTML as esc} from './model.js';
import {lineChart,scatterChart,barChart} from './charts.js?v=20261023-timing';

const main=document.querySelector('main');
let D,Domestic,Timing,Recent,Forecast;
const pages=['domestic','forecast','compare','recent','prices','correlations','mining','quality','archive-quality'];
const state={page:'domestic',forecastSeries:'KR_21694499',timingCategory:'CPU',timingProduct:'21694499',timingHorizon:'12',timingUrgency:'flexible',timingFrequency:'weekly',recentPart:'B07STGGQ18',recentMarket:'AMD',recentYear:'all',recentLag:'0',domCategory:'all',domCohort:'original',domProduct:'21694499',domBasis:'delivered',domQuote:'median3',domCpu:'multi',domPlatform:'all',domGpu:'suite',domGpuScope:'tier',domVram:'any',domSsd:'capacity',domFrequency:'weekly',domSurface:'both',category:'CPU',gpu:'3070',source:'retail',year:'all',scale:'index',stock:'AMD',metric:'eth_price',corrCategory:'CPU',corrStock:'AMD',corrMode:'returns',lag:0,miningGpu:'3070',miningSource:'retail',miningMetric:'fees_excluded_proxy',miningMode:'changes'};
const metricNames={eth_price:'ETH 가격',fees_included_proxy:'수수료 포함 대용 A',fees_excluded_proxy:'수수료 제외 대용 B'};
const events=[{date:'2021-08-05',label:'런던 · 2021.08.05'},{date:'2022-09-15',label:'머지 · 2022.09.15'}];
const $=selector=>main.querySelector(selector);
const options=(values,selected)=>values.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');
const segments=(action,values,selected,compact=false)=>`<div class="segmented ${compact?'compact':''}" role="group" aria-label="${esc(action)}">${values.map(([v,label])=>`<button type="button" data-action="${action}" data-value="${v}" class="${String(v)===String(selected)?'active':''}" aria-pressed="${String(v)===String(selected)}">${label}</button>`).join('')}</div>`;
const select=(id,label,values,selected)=>`<label class="control" for="${id}">${label}<select id="${id}" aria-label="${label}" data-select="${id}">${options(values,selected)}</select></label>`;
const stockOptions=()=>D.stocks.map(s=>[s.symbol,COMPANY_NAMES[s.symbol]??s.name]);
const download=(file,label='CSV 다운로드')=>`<a class="button" href="./data/downloads/${file}" download>${label} <span aria-hidden="true">↓</span></a>`;
const header=(eyebrow,title,subtitle,action='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;
const kpi=(label,value,unit,detail,extra='')=>`<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-number ${extra}">${value}<span class="unit">${unit}</span></div><div class="kpi-detail">${detail}</div></div>`;
const note=(html,green=false)=>`<div class="note ${green?'green':''}"><span class="note-icon" aria-hidden="true">ⓘ</span><div>${html}</div></div>`;
const legend=series=>`<div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('')}</div>`;
const table=(headers,rows)=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const strip=(points,{value='price',date='date',status=null}={})=>`<div class="availability" role="img" aria-label="${points.filter(p=>finite(p[value])).length}개 유효 관측 / ${points.length}개 기간">${points.map(p=>{let cls=finite(p[value])?'yes':'';if(status&&p[status]==='mixed')cls='partial';if(status&&p[status]==='terminated')cls='terminated';return `<span class="${cls}" title="${p[date]} · ${cls==='yes'?'유효 관측':cls==='partial'?'머지 혼합 주':cls==='terminated'?'ETH PoW 종료':'미관측'}"></span>`;}).join('')}</div>`;
const yearLabels=(year='all')=>year==='all'?'<div class="availability-years"><span>2020</span><span>2021</span><span>2022</span></div>':`<div class="availability-years"><span>${year}.01</span><span>${year}.07</span><span>${year}.12</span></div>`;
function product(category){return D.products.find(p=>p.category===category);}
function stock(symbol){return D.stocks.find(p=>p.symbol===symbol);}
function priceSeries(){
  if(state.category!=='GPU'){
    const p=product(state.category),s=stock(state.stock);
    return {name:p.name,currency:p.currency,frequency:'주별',basis:'Amazon.com · 해당 주 마지막 유효 호가',primary:p.weeks.map(w=>({date:w.date,value:w.price})),
      secondary:s.weeks.map(w=>({date:w.date,value:w.price})),secondaryName:COMPANY_NAMES[s.symbol],secondaryUnit:`${s.currency} · 배당·분할 수정주가`,coverage:p.weeks,download:'cpu_ssd_weekly.csv',caveat:'두 개의 개별 SKU를 관측했습니다. CPU·SSD 시장 전체나 현재 적정가를 대표하지 않습니다.'};
  }
  const id=state.gpu,name=GPU_NAMES[id],monthly=state.source==='monthly';
  const rows=monthly?D.gpu.monthly.filter(r=>String(r.gpu)===id):D.gpu.retail.filter(r=>String(r.series_id)===id);
  const field=monthly?'price_usd':'value',suffix=monthly?'mean':'7d';
  return {name,currency:monthly?'USD':'EUR',frequency:monthly?'월별':'실제 조사일',basis:monthly?'미국 eBay · 월별 판매완료 목록 평균':'독일·오스트리아 소매 · 재고 있는 최저 호가',primary:rows.map(r=>({date:monthly?r.month+'-15':r.observation_date,value:r[field]})),
    secondary:rows.map(r=>({date:monthly?r.month+'-15':r.observation_date,value:r[`${state.metric}_${suffix}`]})),secondaryName:metricNames[state.metric],secondaryUnit:state.metric==='eth_price'?'USD':'USD/일/100MH/s · 네트워크 대용',
    coverage:monthly?rows.map(r=>({date:r.month,price:r.price_usd})):D.gpu.weekly.filter(r=>String(r.series_id)===id).map(r=>({date:r.week_end,price:r.value})),download:monthly?'gpu_monthly.csv':'gpu_snapshots.csv',
    caveat:monthly?'월별 집계를 사용합니다. 신품·중고·판매자·LHR 구성 변화는 통제하지 못했습니다.':'2020년 원문 수치와 머지 이후 소매 가격은 미확보입니다. 관측 간격은 대체로 3주이며 주별 변화율이 아닙니다.'};
}
function renderPrices(){
  const p=priceSeries(),primary=inYear(p.primary,state.year),secondary=inYear(p.secondary,state.year),s=stats(primary);
  const coverage=inYear(p.coverage,state.year),nCoverage=coverage.filter(r=>finite(r.price)).length;
  const indexed=state.scale==='index',range={start:state.year==='all'?'2020-01-01':`${state.year}-01-01`,end:state.year==='all'?'2022-12-31':`${state.year}-12-31`};
  const displayDate=d=>p.frequency==='월별'?d.slice(0,7)+' 월평균':d;
  const raw=[{name:p.name,color:COLORS[0],points:primary},{name:p.secondaryName,color:COLORS[1],points:secondary}],chartSeries=indexed?normalizeTogether(raw):[raw[0]];
  const commonDate=chartSeries[0].baseDate;
  const extra=state.category==='GPU'?
    select('gpu','제품',Object.entries(GPU_NAMES),state.gpu)+select('source','출처',[['retail','소매 · EUR'],['monthly','eBay · USD']],state.source):'';
  main.innerHTML=header('PRICE EXPLORER','가격의 흐름을 읽다','가격이 움직인 시간, 그리고 실제로 관측한 구간을 확인하세요.',download(p.download))+
  `<div class="controls"><div class="control-group">${segments('category',[['CPU','CPU'],['SSD','SSD'],['GPU','GPU']],state.category)}${extra}</div><div class="control-group">${segments('year',[['all','전체'],['2020','2020'],['2021','2021'],['2022','2022']],state.year,true)}</div></div>`+
  `<div class="kpis">${kpi('마지막 관측 가격',s.last?num(s.last.value):'—',p.currency,s.last?`${displayDate(s.last.date)} · 실시간 가격 아님`:'선택 기간에 관측 없음')}${kpi('첫 관측 대비 변화',pct(s.change),'',s.first?`${displayDate(s.first.date)} → ${displayDate(s.last.date)}`:'비교할 관측이 없습니다.','negative')}${kpi('실제 가격 표본',String(s.n),p.frequency==='주별'?'주':p.frequency==='월별'?'개월':'시점',`선택 기간 · ${p.frequency} 관측`)}${kpi('달력상 미관측',String(coverage.length-nCoverage),state.category==='GPU'&&state.source==='monthly'?'개월':'주',`유효 ${nCoverage} / ${coverage.length}개 기간 · 이월·보간 없음`)}</div>`+
  `<div class="board"><section class="panel"><div class="panel-head"><div><h2>${esc(p.name)}</h2><p class="panel-subtitle">${p.basis}</p></div><span class="pill">${p.frequency} 관측</span></div>
  <div class="panel-inner" style="padding-bottom:0"><div class="control-group">${segments('scale',[['index','기준일 = 100'],['original','원 가격']],state.scale,true)}${state.category==='GPU'?select('metric','비교',Object.entries(metricNames),state.metric):select('stock','비교',stockOptions(),state.stock)}</div></div>
  <div id="price-chart" class="chart-zone"></div>${legend(chartSeries)}<div class="panel-foot">${indexed?commonDate?`공통 첫 유효 ${p.frequency==='월별'?'월':'날짜'} ${displayDate(commonDate)} = 100. 이전 구간은 표시하지 않습니다.`:'두 계열이 함께 관측된 기준일이 없어 비교 지수를 표시하지 않습니다.':`${p.currency} 원 가격. 비교 계열은 아래 별도 축으로 표시합니다.`}<br>점은 실제 ${p.frequency==='월별'?'월별 집계':'관측'} · ${state.category==='GPU'?'선은 관측 사이의 안내선':'빈 구간은 미관측'} · 커서 또는 좌우 방향키로 날짜별 값을 확인할 수 있습니다.</div></section>
  <aside class="panel insight"><div class="eyebrow">READ THE DATA</div><h2>${state.category==='GPU'?'급등과 하락 사이,<br>채굴 붐의 흔적':state.category==='CPU'?'가격은 내렸지만,<br>주가와는 다른 흐름':'용량이 같아도,<br>가격은 시간에 따라'}</h2><p>${p.caveat}</p><div class="insight-divider"></div><div class="tiny-stat"><span>첫 유효 가격</span><strong>${s.first?num(s.first.value):'—'}</strong></div><div class="tiny-stat"><span>마지막 유효 가격</span><strong>${s.last?num(s.last.value):'—'}</strong></div><div class="tiny-stat"><span>선택 기간 관측률</span><strong>${coverage.length?pct(nCoverage/coverage.length).replace('+',''):'—'}</strong></div><div class="callout">${state.category==='GPU'?'실측 채굴 순이익은 미확보입니다. 네트워크 대용과 실제 카드 수익을 구분해 읽어주세요.':'가격 수준의 동행과 주별 변화율의 동행은 다릅니다. 상관 화면에서 두 값을 비교할 수 있습니다.'}<br><a href="#${state.category==='GPU'?'mining':'correlations'}">분석 자세히 보기 ↗</a></div></aside></div>`+
  (!indexed?`<section class="panel section-block"><div class="panel-head"><div><h2>${esc(p.secondaryName)} · 비교 계열</h2><p class="panel-subtitle">${p.secondaryUnit} · 서로 다른 단위는 별도 축에서 비교</p></div></div><div id="secondary-chart" class="chart-zone"></div></section>`:'')+
  `<div class="two-col"><section class="panel"><div class="panel-inner"><div class="section-row"><h2>실제 관측 범위</h2><span>파랑·초록: 유효 / 회색: 미관측</span></div><div class="strip-label"><span>${esc(p.name)}</span><b>${nCoverage} / ${coverage.length}</b></div>${strip(coverage)}${yearLabels(state.year)}<p class="small-copy" style="margin-top:12px">${state.category==='GPU'&&state.source==='retail'?'조사일 표본과 달력 주 표본 수는 다릅니다. 한 주에 두 번 조사한 가격은 주별 표에서 마지막 값만 선택합니다.':'가격이 없는 기간은 빈칸으로 남겼습니다. 결측 양옆을 연결해 변화율 표본으로 만들지 않습니다.'}</p></div></section><div>${note(state.category==='GPU'?'<strong>해석 범위</strong><br>소매 EUR와 eBay USD는 다른 시장·가격 정의입니다. 하나의 연속 가격으로 합치지 않았습니다. 수익 대용에는 Beacon 보상과 소각 수수료의 편향이 있습니다.':'<strong>표본은 제품별로 다릅니다</strong><br>전체 156주 중 CPU는 148주·SSD는 135주입니다. 바로 전 주가 없으면 변화율도 비워 실제 변화율 표본은 140·122개입니다.')}<p class="small-copy" style="margin-top:12px">${state.category==='GPU'?'출처: 3DCenter · Tom’s Hardware/eBay · Coin Metrics':'출처: PriceHistory의 Amazon.com 호가 · Yahoo 수정주가'} · <a href="#quality">전처리·출처 확인 ↗</a></p></div></div>`;
  lineChart($('#price-chart'),chartSeries,{title:`${p.name} 가격 추이`,unit:indexed?'공통 기준일 = 100':p.currency,...range,events:state.category==='GPU'?events:[],showPoints:state.category==='GPU',monthly:p.frequency==='월별'});
  if(!indexed)lineChart($('#secondary-chart'),[raw[1]],{title:p.secondaryName,unit:p.secondaryUnit,...range,events:state.category==='GPU'?events:[],monthly:p.frequency==='월별'});
}
function renderCorrelations(){
  const p=product(state.corrCategory),s=stock(state.corrStock),mode=state.corrMode;
  const selected=D.stockCorrelations.find(r=>r.product_id===p.id&&r.symbol===s.symbol);
  const lagRows=D.stockLags.filter(r=>r.product_id===p.id&&r.symbol===s.symbol).sort((a,b)=>a.lag_weeks-b.lag_weeks);
  const lagRow=lagRows.find(r=>r.lag_weeks===state.lag);
  const pairs=stockPairs(p,s,mode,mode==='returns'?state.lag:0),r=mode==='levels'?selected.level_pearson:state.lag===0?selected.return_pearson:lagRow.pearson,n=mode==='levels'?selected.n_level:state.lag===0?selected.n_return:lagRow.n;
  const heatRows=D.products.map(p=>`<div class="heat-label row">${p.category} 가격</div>`+D.stocks.map(s=>{const c=D.stockCorrelations.find(r=>r.product_id===p.id&&r.symbol===s.symbol),v=mode==='levels'?c.level_pearson:c.return_pearson,n=mode==='levels'?c.n_level:c.n_return;
    const alpha=Math.min(.7,Math.abs(v)*.8),color=v<0?`rgba(130,112,184,${.08+alpha})`:`rgba(36,132,90,${.06+alpha})`;
    return `<button class="heat-cell ${state.corrCategory===p.category&&state.corrStock===s.symbol?'selected':''}" style="background:${color};color:${v<0?'#69568d':'#305b3a'}" data-action="heat" data-value="${p.category}:${s.symbol}" aria-label="${p.category}와 ${COMPANY_NAMES[s.symbol]} 상관 ${signed(v)}, 표본 ${n}" aria-pressed="${state.corrCategory===p.category&&state.corrStock===s.symbol}"><strong>${signed(v)}</strong><small>n = ${n}</small></button>`;}).join('')).join('');
  main.innerHTML=header('CORRELATION LAB','함께 움직였을까','가격 수준과 변화율을 분리해, 부품과 여섯 기업의 관계를 살펴봅니다.',download('stock_correlations.csv'))+
  `<div class="controls"><div class="control-group">${segments('corrMode',[['returns','주별 변화율'],['levels','가격 수준']],mode)}<span class="pill">2020–2022 전체 구간 · 12조합</span></div><span class="small-copy">r: −1 ~ +1 · 인과관계·예측력과 구분</span></div>
  <section class="panel"><div class="panel-head"><div><h2>부품 × 기업 상관 지도</h2><p class="panel-subtitle">셀을 선택하면 실제 관측 쌍과 시차별 결과를 볼 수 있습니다. 아래 값은 모두 같은 주(L=0)입니다.</p></div><div><div class="scale-bar"></div><div class="scale-label"><span>−1</span><span>0</span><span>+1</span></div></div></div><div class="heat-scroll"><div class="correlation-grid"><div></div>${D.stocks.map(s=>`<div class="heat-label">${COMPANY_NAMES[s.symbol]}</div>`).join('')}${heatRows}</div></div></section>
  <div class="section-block">${note('<strong>12조합·204개 시차 비교의 한계</strong> — 가장 큰 상관을 사후에 골라도 검증된 예측 신호가 아닙니다. 전체 시차의 다중 비교 보정 후 q &lt; 0.05인 결과는 없었습니다. 가격 수준에는 유의성 판정을 붙이지 않습니다.',true)}</div>
  <div class="kpis section-block">${kpi('선택한 조합',state.corrCategory,'↔ '+COMPANY_NAMES[s.symbol],p.name)}${kpi(mode==='levels'?'가격 수준 상관 r':'로그 변화율 상관 r',signed(r),'',mode==='levels'?'같은 주 가격 수준':`시차 L = ${state.lag>0?'+':''}${state.lag}주`)}${kpi('실제 겹치는 표본',String(n),'쌍',mode==='levels'?'두 값이 모두 있는 주만 사용':'앞·뒤 주 결측과 시차 적용 후 재집계')}${kpi('전체 시차 보정 q',mode==='returns'?num(lagRow.q_shift_bh_all_lags,3):'—','',mode==='returns'?'BH 보정 · 204개 비교':'가격 수준의 유의성은 검정하지 않음')}</div>
  <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>${state.corrCategory} × ${COMPANY_NAMES[s.symbol]}</h2><p class="panel-subtitle">점 하나 = 실제 관측 쌍 하나 · n=${n}</p></div><span class="pill">${mode==='levels'?'수준 비교':'로그 변화율'}</span></div><div id="scatter-chart" class="chart-zone"></div><div class="panel-foot">${mode==='levels'?`X: ${s.currency} 수정주가 · Y: USD 부품 가격. 장기 추세와 환율 영향을 통제하지 못했습니다.`:'로그 변화율 ×100을 %로 표시합니다. 같은 가격이 반복된 0 변화율도 유효 관측으로 유지합니다.'}</div></section>
  <section class="panel"><div class="panel-head"><div><h2>어느 쪽이 먼저 움직였을까</h2><p class="panel-subtitle">±8주 로그 변화율 상관 · 선택할 때마다 실제 n 확인</p></div><span class="pill purple">탐색적 분석</span></div><label class="lag-control" for="lag"><span>−8주</span><input id="lag" data-select="lag" type="range" min="-8" max="8" step="1" value="${state.lag}" ${mode==='levels'?'disabled':''}><span>+8주</span><output for="lag">${state.lag>0?'+':''}${state.lag}주</output></label><div id="lag-chart" class="chart-zone"></div><div class="panel-foot">양수 L: 주가가 먼저 / 음수 L: 부품 가격이 먼저.<br>${mode==='levels'?'가격 수준 모드에서는 시차 선택을 비활성화합니다. 시차 그림은 변화율 분석 결과입니다.':`선택한 L=${state.lag}: r=${signed(lagRow.pearson)}, n=${lagRow.n}.`} 최대 계수는 최적 시차를 뜻하지 않습니다.</div></section></div>
  <div class="section-block">${note(`<strong>개별 구간과 전체 비교를 구분합니다.</strong> 같은 주 변화율의 4주 블록 부트스트랩 95% 구간은 [${signed(selected.return_ci_low_block4)}, ${signed(selected.return_ci_high_block4)}]입니다. 이는 L=0의 개별 근사 구간이며 전체 조합의 동시 구간이 아닙니다. 삼성전자·SK하이닉스는 일부 주의 마지막 실제 거래일 자료가 누락됐고, 원화 주가를 달러 수익률로 환산하지 않았습니다.`)}</div>`;
  scatterChart($('#scatter-chart'),pairs,{title:`${state.corrCategory}와 ${COMPANY_NAMES[s.symbol]} 실제 관측 쌍`,percent:mode==='returns',xLabel:mode==='returns'?`${COMPANY_NAMES[s.symbol]} 로그 변화율`:`${COMPANY_NAMES[s.symbol]} 수정주가 (${s.currency})`,yLabel:mode==='returns'?`${state.corrCategory} 로그 변화율`:`${state.corrCategory} 가격 (USD)`});
  barChart($('#lag-chart'),lagRows,{selected:mode==='returns'?state.lag:0});
}
function renderMining(){
  const id=state.miningGpu,label=GPU_NAMES[id];
  const peak=D.gpu.changes.find(r=>String(r.series_id)===id&&r.comparison==='observed_peak_to_last_premerge'),event=D.gpu.changes.find(r=>String(r.series_id)===id&&r.comparison==='premerge_Jul_Aug_vs_postmerge_Oct_Nov');
  const r=miningCorrelation(D,id,state.miningSource,state.miningMetric,state.miningMode==='levels'?'levels':'changes');
  const monthlySeries=Object.keys(GPU_NAMES).map((gpu,i)=>({name:GPU_NAMES[gpu],color:COLORS[i],width:gpu===id?3:1.5,points:D.gpu.monthly.filter(r=>String(r.gpu)===gpu).map(r=>({date:r.month+'-15',value:r.price_usd}))}));
  const source=state.miningSource==='retail'?'소매 관측 간':'eBay 월별';
  const cryptoSeries=[{name:'ETH 가격',color:COLORS[1],points:D.eth.daily.map(r=>({date:r.date,value:r.price}))}];
  const smooth=field=>D.eth.daily.map((r,i,all)=>{const win=all.slice(Math.max(0,i-6),i+1);return {date:r.date,value:win.length===7&&win.every(v=>finite(v[field]))?win.reduce((a,v)=>a+v[field],0)/7:null};});
  const proxySeries=[{name:'수수료 포함 대용 A',color:COLORS[2],points:smooth('proxyA')},{name:'수수료 제외 대용 B',color:COLORS[0],points:smooth('proxyB')}];
  const summaryRows=Object.entries(GPU_NAMES).map(([gpu,name])=>{const c=D.gpu.changes.find(r=>String(r.series_id)===gpu&&r.comparison==='premerge_Jul_Aug_vs_postmerge_Oct_Nov');return [`<strong>${name}</strong>`,num(c.before_value,1),num(c.after_value,1),`<strong>${pct(c.change_fraction)}</strong>`,'2 / 2개월'];});
  main.innerHTML=header('MINING BOOM / 2021–2022','채굴 붐이 남긴 가격의 흔적','GPU 가격과 ETH, 네트워크 수익 대용을 같은 시점에서 비교합니다.',download('gpu_changes.csv'))+
  `<div class="event-banner"><div class="event-date">ETHEREUM MERGE<strong>2022.09.15</strong></div><div><b>ETH의 작업증명(PoW) 채굴 종료</b><p>머지 전부터 가격은 하락했습니다. 전후 가격 차이를 머지만의 효과로 단정하지 않습니다.</p></div><span class="pill amber">인과 효과 미식별</span></div>
  <div class="controls"><div class="control-group">${segments('miningGpu',Object.entries(GPU_NAMES),id)}</div><span class="small-copy">소매 EUR · eBay USD는 분리</span></div>
  <div class="kpis">${kpi('소매 최고→머지 직전',pct(peak.change_fraction),'',`${num(peak.before_value,0)} → ${num(peak.after_value,0)} EUR`,'negative')}${kpi('eBay 머지 전후 차이',pct(event.change_fraction),'','7~8월 평균 → 10~11월 평균','negative')}${kpi('eBay 실제 관측',String(D.gpu.monthly.filter(r=>String(r.gpu)===id&&finite(r.price_usd)).length),'개월','2021.09–2022.12 · 변화율 15개')}${kpi('네트워크 대용 관측','988','일','2020.01.01–2022.09.14 · 실측 순이익 아님')}</div>
  <section class="panel"><div class="panel-head"><div><h2>머지 전후, 실제 월별 판매가격</h2><p class="panel-subtitle">전: 2022년 7·8월 / 후: 10·11월 · 9월은 전환 전후 혼합 월</p></div><span class="pill">각 2개월 단순 평균</span></div><div id="mining-prices" class="chart-zone"></div>${legend(monthlySeries)}${table(['제품','전 평균 (USD)','후 평균 (USD)','변화','전 / 후 표본'],summaryRows)}<div class="panel-foot">각 월에 동일한 가중치를 부여합니다. 판매량 가중 평균이 아닙니다. 소매 관측 최고가는 2021-05-16, 머지 직전 마지막 소매 관측은 2022-09-11입니다. 판매자·신품/중고·LHR 구성을 통제하지 못했습니다.</div></section>
  <div class="timeline-notes"><div class="timeline-note"><time>2021.05.16</time><strong>확보된 소매 관측 중 최고가</strong><p>실제 조사일 사이에 더 높은 가격이 있었는지는 알 수 없습니다. 첫 관측도 이미 붐이 진행된 시점입니다.</p></div><div class="timeline-note"><time>2021.08.05</time><strong>런던 · 수수료 소각 도입</strong><p>이후 총수수료에는 광부가 받지 못한 소각분이 포함됩니다. 대용 A의 해석이 달라집니다.</p></div><div class="timeline-note"><time>2022.09.15</time><strong>머지 · ETH PoW 종료</strong><p>ETH 채굴 지표는 해당 없음으로 처리합니다. 다른 코인으로 전환한 GPU 채굴 수익은 미포함입니다.</p></div></div>
  <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>이더리움 가격</h2><p class="panel-subtitle">UTC 일 마감 · 유효 1,096일</p></div></div><div id="eth-chart" class="chart-zone"></div><div class="panel-foot">2020–2022 전체 가격 자료. GPU의 2020년 수치 관측은 미확보입니다.</div></section><section class="panel"><div class="panel-head"><div><h2>네트워크 수익 대용 · 7일 평균</h2><p class="panel-subtitle">고정 100MH/s당 USD/일 · 머지 이후 해당 없음</p></div><span class="pill amber">실측 순이익 아님</span></div><div id="proxy-chart" class="chart-zone"></div>${legend(proxySeries)}<div class="panel-foot">A: (발행량+총수수료) × 가격 ÷ 해시레이트 / B: 발행량만 사용. Beacon 스테이킹 발행이 혼입되며 A는 런던 이후 소각분도 포함합니다.</div></section></div>
  <div class="section-block">${note('<strong>채굴 수익성의 제한</strong> — 실제 카드별 해시 성능·소비전력·요금·가동률을 갖춘 실측 순이익은 확보하지 못했습니다. 두 대용 모두 실제 광부 매출의 확정적인 상·하한이 아닙니다. 대용 지표의 감소율로 순이익 감소율이나 투자 회수기간을 계산할 수 없습니다.')}</div>
  <section class="panel section-block"><div class="panel-head"><div><h2>GPU와 ETH·대용 지표의 관계</h2><p class="panel-subtitle">실제 관측 간 변화율과 월별 변화율을 구분합니다. 모든 값은 저장된 전체 구간 분석 결과입니다.</p></div></div><div class="panel-inner"><div class="control-group">${select('miningSource','자료',[['retail','소매 · 실제 조사일'],['monthly','eBay · 월별']],state.miningSource)}${select('miningMetric','비교',Object.entries(metricNames),state.miningMetric)}${segments('miningMode',[['changes','변화율'],['levels','가격 수준']],state.miningMode,true)}</div><div class="metric-row" style="margin-top:22px"><div class="metric-large">${signed(r?.pearson)}</div><div><span class="pill">실제 n = ${r?.n??0}</span><p class="small-copy">${label} × ${metricNames[state.miningMetric]} · ${source} ${state.miningMode==='levels'?'수준':'로그 변화율'}</p></div></div><p class="small-copy" style="margin-top:15px">소매 변화율 간격은 대체로 21일입니다. 주별 변화율이 아닙니다. eBay–ETH는 변화율 n=15, eBay–채굴 대용은 머지 이전 전체 월만 겹쳐 n=11입니다. 높은 수준 상관만으로 인과관계나 예측력을 판단하지 않습니다.</p></div></section>
  <div class="section-block">${note('<strong>기간에 따라 달라지는 관계</strong> — 소매 관측 간 GPU–ETH 변화율 상관은 전체 기간 0.35~0.54였지만, 2022년만 보면 −0.33~0.02였습니다. 전체 구간의 양의 상관을 고정된 구매 규칙으로 사용하기 어렵습니다.',true)}</div>`;
  lineChart($('#mining-prices'),monthlySeries,{title:'머지 전후 GPU eBay 월별 평균가격',unit:'USD · 월평균 판매가격',start:'2021-09-01',end:'2022-12-31',events:[events[1]],showPoints:true,monthly:true});
  lineChart($('#eth-chart'),cryptoSeries,{title:'이더리움 일별 가격',unit:'USD',start:'2020-01-01',end:'2022-12-31',events,height:310});
  lineChart($('#proxy-chart'),proxySeries,{title:'네트워크 수익 대용 A와 B',unit:'USD / 일 / 100MH/s',start:'2020-01-01',end:'2022-12-31',events,height:310});
}
function renderQuality(){
  const coverageRows=D.products.map(p=>[p.category,esc(p.name),'주별',`${p.coverage.observed} / 156주`,`${p.coverage.returns}개`,`${156-p.coverage.observed}주`]);
  for(const [id,name] of Object.entries(GPU_NAMES)){const snap=D.gpu.retail.filter(r=>String(r.series_id)===id&&finite(r.value)),w=D.gpu.weekly.filter(r=>String(r.series_id)===id),n=w.filter(r=>finite(r.value)).length;coverageRows.push(['GPU',name,'소매 조사일',`${snap.length}시점 / ${n}주`,`${w.filter(r=>finite(r.weekly_return_log)).length}개 (인접 주)`,`${156-n}주`]);}
  coverageRows.push(['GPU','eBay · 제품별','월별','16 / 36개월','15개 (월간)','20개월']);
  const allCoverage=D.products.map(p=>({name:p.name,rows:p.weeks,n:p.coverage.observed}));
  for(const [id,name] of Object.entries(GPU_NAMES)){const rows=D.gpu.weekly.filter(r=>String(r.series_id)===id).map(r=>({date:r.week_end,price:r.value}));allCoverage.push({name,rows,n:rows.filter(r=>finite(r.price)).length});}
  main.innerHTML=header('DATA & METHODS','숫자가 말할 수 있는 범위','출처와 표본, 결측 처리와 대용 지표의 한계를 투명하게 확인합니다.',`<a class="button" href="./data/dashboard.json" download>전체 분석 JSON ↓</a>`)+
  `<div class="kpis">${kpi('가격 분석 제품','5','제품','CPU 1 · SSD 1 · GPU 3')}${kpi('주가 비교 기업','6','기업','미국 4 · 한국 2 · 배당·분할 수정주가')}${kpi('분석 달력','156','주','토~금 · 2020.01.10–2022.12.30')}${kpi('분석 기준일','10.22','2026','과거 자료 스냅샷 · 실시간 갱신 없음')}</div>
  <section class="panel"><div class="panel-head"><div><h2>실제 표본 수와 결측</h2><p class="panel-subtitle">조사일·달력주·월별 표본은 서로 다른 단위입니다. 중복 집계하지 않습니다.</p></div><span class="pill">무보간 원칙</span></div><div style="margin-top:15px">${table(['분류','제품 / 자료','빈도','가격 유효 관측','유효 변화율','미확보'],coverageRows)}</div><div class="panel-foot">ETH 가격 1,096일 / 수익 대용 988일. 머지 부분일 1일·종료 107일은 일반 결측과 구분합니다. 주별 대용은 완전한 140주·혼합 1주(유효 5일)·종료 15주입니다.</div></section>
  <section class="panel section-block"><div class="panel-inner"><div class="section-row"><h2>관측 지도 · 주별</h2><span>초록: 가격 확보 / 회색: 미관측</span></div>${allCoverage.map(c=>`<div class="strip-label"><span>${esc(c.name)}</span><b>${c.n} / 156주</b></div>${strip(c.rows)}`).join('')}${yearLabels()}<div class="strip-label"><span>ETH 네트워크 수익 대용</span><b>완전한 140 / 156주</b></div>${strip(D.eth.weekly.map(w=>({date:w.week_end,price:w.n_rev_days===7?w.rev_usd_per100mh_week_mean:null,status:w.pow_status})),{status:'status'})}${yearLabels()}<p class="small-copy" style="margin-top:10px">황색: 머지 혼합 주 / 살구색: ETH PoW 종료. 선택한 기간·자료의 빈칸을 다른 자료로 채우지 않습니다.</p></div></section>
  <div class="section-block"><div class="section-row"><h2>분석을 읽기 전, 여섯 가지 한계</h2><span>OBSERVATION ≠ CAUSATION</span></div><div class="limits">
  <article class="limit-card"><div class="number">01 / COVERAGE</div><h3>2020년 GPU 수치 관측 미확보</h3><p>선정한 GPU의 2020년 원문 숫자는 없습니다. 이미지 차트와 보간된 외부 CSV를 실관측으로 사용하지 않았습니다. 붐 시작 전후를 완전하게 비교할 수 없습니다.</p></article>
  <article class="limit-card"><div class="number">02 / PROFITABILITY</div><h3>실제 채굴 순이익을 확보하지 못했습니다</h3><p>A/B는 고정 100MH/s당 네트워크 대용입니다. 카드별 전력·요금·LHR·가동률·풀 수수료와 MEV를 반영하지 못합니다. Beacon 보상이 섞이고, A에는 런던 이후 소각 수수료도 포함됩니다.</p></article>
  <article class="limit-card"><div class="number">03 / PRICE BASIS</div><h3>소매 호가와 평균 판매가격의 차이</h3><p>Amazon USD 호가, 독일 EUR 최저 호가, 미국 eBay USD 월별 판매가격은 각각 별도 자료입니다. SKU·판매자·신품/중고 구성과 환율 영향을 통제하지 못했습니다.</p></article>
  <article class="limit-card"><div class="number">04 / MISSINGNESS</div><h3>결측은 단순한 표본 감소 이상일 수 있습니다</h3><p>가격 공란은 그대로 유지합니다. 품절·가격 급변과 결측이 무관하다는 보장은 없습니다. 현재·직전 주가 모두 유효할 때만 주별 변화율을 계산합니다.</p></article>
  <article class="limit-card"><div class="number">05 / COMPARISONS</div><h3>높은 상관과 예측력은 다릅니다</h3><p>장기 추세·자기상관을 고려해야 합니다. ±8주를 포함한 204개 비교의 다중 비교 보정 후 유의한 결과는 없었습니다. 많은 시차 중 최대값을 구매 신호로 사용하지 않습니다.</p></article>
  <article class="limit-card"><div class="number">06 / STOCK TIMING</div><h3>일부 한국 주가의 마지막 세션 누락</h3><p>삼성전자 1주·SK하이닉스 2주는 주 내 마지막 실제 거래일보다 앞선 유효일을 사용했습니다. 현지 거래일을 맞췄지만 장 마감 시각·가격 원본 시각대는 완전히 일치하지 않습니다.</p></article></div></div>
  <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>출처와 지표 정의</h2><p class="panel-subtitle">공개 데이터 · 원본과 입력 해시 보존</p></div></div><div class="panel-inner source-list">${D.sources.map(s=>`<div class="source-item"><div><strong>${esc(s.name)}</strong><p>${esc(s.scope)}</p></div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">원문 ↗</a></div>`).join('')}</div></section>
  <section class="panel"><div class="panel-head"><div><h2>데이터 내려받기</h2><p class="panel-subtitle">화면과 같은 검증된 분석 산출물 · CSV / JSON</p></div></div><div class="panel-inner"><h3>가격·주가</h3><div class="download-list">${download('cpu_ssd_weekly.csv','주별 결합')}${download('stock_correlations.csv','상관 결과')}${download('stock_lags.csv','시차별 결과')}</div><h3 style="margin-top:24px">GPU·이더리움</h3><div class="download-list">${download('gpu_snapshots.csv','소매 관측일')}${download('gpu_monthly.csv','eBay 월별')}${download('gpu_correlations.csv','GPU 상관')}${download('gpu_changes.csv','전후 비교')}${download('eth_daily.csv','ETH 일별')}</div><h3 style="margin-top:24px">분석 보고서</h3><div class="download-list"><a class="button" href="./reports/cpu-ssd.md" download>CPU·SSD 보고서 ↓</a><a class="button" href="./reports/gpu-mining.md" download>GPU·채굴 보고서 ↓</a><a class="button" href="./reports/analysis-bundle.zip" download>그림·CSV 포함 전체 ZIP ↓</a></div><p class="small-copy" style="margin-top:18px">개별 보고서는 텍스트 파일입니다. 그림·관련 CSV·방법 문서를 함께 보려면 전체 ZIP을 내려받으세요. 화면의 반올림 전 값과 실제 n은 CSV에서 확인할 수 있습니다. JSON의 inputHashes로 입력 파일의 SHA-256을 추적할 수 있습니다.</p></div></section></div>
  <div class="section-block">${note('<strong>국내 기존 8개+비교 견적 13개의 가격·구매 판단을 볼 수 있습니다.</strong> <a href="#domestic">국내 구매 화면 ↗</a>에서 최신 견적과 제한된 성능 근거를 확인하세요. 이 화면의 5개 제품·156주는 2020–2022년 해외 분석만의 표본이며 국내 자료와 별개입니다.',true)}</div>`;
}
function render(){
  const focus=document.activeElement?.id;
  document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===(['prices','correlations'].includes(state.page)?'mining':state.page==='archive-quality'?'quality':state.page));if(el.dataset.nav===(['prices','correlations'].includes(state.page)?'mining':state.page==='archive-quality'?'quality':state.page))el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  ({domestic:()=>renderTiming(main,Domestic,Timing,state,Forecast),forecast:()=>renderForecast(main,Forecast,state),compare:()=>renderDomestic(main,Domestic,state),recent:()=>renderRecent(main,Recent,state),prices:renderPrices,correlations:renderCorrelations,mining:renderMining,quality:()=>renderDataHub(main,Domestic,Timing,Recent,Forecast),'archive-quality':renderQuality}[state.page]??renderPrices)();
  if(['prices','correlations','mining'].includes(state.page))archiveNav(main,state.page);
  if(state.page==='compare')main.insertAdjacentHTML('afterbegin','<div class="t-notice">이 화면은 현재 성능 대비 가격 비교입니다. <a href="#domestic">가격 추세에 따른 구매 시점 판단 →</a></div>');
  document.title=({domestic:'지금 살까, 기다릴까',forecast:'3개월 예측 검증',compare:'성능·가격 비교',recent:'최근 시장 2023–2026','archive-quality':'과거 분석 근거',prices:'가격 추이',correlations:'주가와 상관',mining:'채굴 붐',quality:'데이터와 한계'}[state.page])+' · Parts Observatory';
  if(focus)document.getElementById(focus)?.focus({preventScroll:true});
}
main.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'auto'});return;}const b=e.target.closest('[data-action]');if(!b)return;const {action,value}=b.dataset;
  if(action==='openForecast'){state.forecastSeries=value;location.hash='forecast';return;}
  if(action==='inspectProduct'){state.domProduct=value;state.domCategory=[...Domestic.products,...Domestic.marketReferences].find(p=>p.id===value)?.category??'all';state.domCohort='all';state.compareFocus=true;location.hash='compare';return;}
  if(action==='timingCategory')state.timingProduct=({CPU:'21694499',RAM:'14907467',SSD:'18297002',GPU:'99839876'})[value];
  if(action==='timingProduct')state.timingCategory=[...Domestic.products,...Domestic.marketReferences].find(p=>p.id===value)?.category??state.timingCategory;
  if(action==='heat'){[state.corrCategory,state.corrStock]=value.split(':');state.lag=0;}else state[action]=value;
  if(action==='category'&&value!=='GPU')state.stock=value==='CPU'?'AMD':'005930';
  if(action==='corrMode'&&value==='levels')state.lag=0;
  if(action==='domProduct'){
    const product=[...Domestic.products,...Domestic.marketReferences].find(p=>p.id===value);
    if(product){state.domCohort=product.cohort;if(state.domCategory!=='all')state.domCategory=product.category;}
  }
  render();
  if(action==='domProduct')main.querySelector('.domestic-detail-title')?.scrollIntoView({behavior:'auto',block:'start'});
});
main.addEventListener('change',e=>{if(!e.target.dataset.select)return;state[e.target.dataset.select]=e.target.dataset.select==='lag'?Number(e.target.value):e.target.value;render();});
main.addEventListener('input',e=>{if(e.target.dataset.select==='lag'){state.lag=Number(e.target.value);render();}});
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'domestic';if(!pages.includes(state.page))state.page='domestic';if(D)render();if(state.page==='compare'&&state.compareFocus){state.compareFocus=false;main.querySelector('.domestic-detail-title')?.scrollIntoView({behavior:'auto',block:'start'});}else window.scrollTo(0,0);});
let resizeTimer;
let lastWidth=window.innerWidth;
window.addEventListener('resize',()=>{if(window.innerWidth===lastWidth)return;lastWidth=window.innerWidth;clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(D)render();},160);});
async function load(){try{const response=await fetch('./data/dashboard.json');if(!response.ok)throw new Error(`HTTP ${response.status}`);D=await response.json();const domesticResponse=await fetch('./data/domestic.json');if(!domesticResponse.ok)throw new Error(`국내 자료 HTTP ${domesticResponse.status}`);Domestic=await domesticResponse.json();const additions=await Promise.all(['timing','recent','forecast'].map(async name=>{const r=await fetch('./data/'+name+'.json');if(!r.ok)throw new Error(name+' HTTP '+r.status);return r.json();}));[Timing,Recent,Forecast]=additions;if(Timing.schemaVersion!==1||Recent.schemaVersion!==1||Forecast.schemaVersion!==1)throw new Error('최근 자료 버전 오류');if(Domestic.schemaVersion!==1)throw new Error('국내 자료 버전 오류');if(D.schemaVersion!==1)throw new Error('분석 자료 버전이 올바르지 않습니다.');state.page=location.hash.slice(1)||'domestic';if(!pages.includes(state.page))state.page='domestic';render();}catch(error){console.error(error);main.innerHTML=`<div class="error-box"><h1>분석 자료를 불러오지 못했습니다.</h1><p>네트워크 연결을 확인한 뒤 다시 시도해 주세요. 로컬 실행 시 dashboard/dist를 HTTP 서버로 열어야 합니다.</p><button class="button primary" id="retry">다시 불러오기</button></div>`;$('#retry').addEventListener('click',load);}}
load();
